+type ZoneEditorValue = KidsZone;
+
+type Props = {
+  value: KidsZone[];
+  minPxSize: number;
+  /**
+   * Ref points to the *visible image layer* (not the full viewport).
+   * Editor measures this element to convert px <-> normalized (0..1) values.
+   */
+  layerRef: React.RefObject<HTMLDivElement | null>;
+};
+
+type DragMode =
+  | { type: 'move'; zoneId: string }
+  | { type: 'resize'; zoneId: string; handle: 'nw' | 'ne' | 'sw' | 'se' };
+
+type ActiveDrag = {
+  mode: DragMode;
+  pointerId: number;
+  startClientX: number;
+  startClientY: number;
+  startZone: Pick<KidsZone, 'x' | 'y' | 'width' | 'height'>;
+};
+
+function clampNumber(v: number, min: number, max: number): number {
+  return Math.max(min, Math.min(max, v));
+}
+
+function to01(v: number): number {
+  // Backward compatibility:
+  // - old content used 0..100 (% of image)
+  // - editor outputs 0..1 (normalized)
+  const n = v > 1.001 ? v / 100 : v;
+  return clampNumber(n, 0, 1);
+}
+
+function normalizeZone01(zone: KidsZone): KidsZone {
+  return {
+    ...zone,
+    x: to01(zone.x),
+    y: to01(zone.y),
+    width: to01(zone.width),
+    height: to01(zone.height),
+  };
+}
+
+function roundN(v: number, n: number): number {
+  const p = 10 ** n;
+  return Math.round(v * p) / p;
+}
+
+export default function ZoneEditor({ value, minPxSize, layerRef }: Props) {
+  const { t } = useTranslation();
+
+  const [zones, setZones] = useState<ZoneEditorValue[]>(() => value.map(normalizeZone01));
+  const [activeZoneId, setActiveZoneId] = useState<string>(value[0]?.id ?? '');
+  const [status, setStatus] = useState<'idle' | 'copied' | 'error'>('idle');
