import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import type { KidsZone } from '../types/kidsStory';

// Ensures this file is treated as a module under `isolatedModules` in CRA/Babel builds.
export {};

type ResizeHandle = 'nw' | 'ne' | 'sw' | 'se';

type Props = {
  zones: KidsZone[];
  containerWidth: number;
  containerHeight: number;
  onChangeZones: (zones: KidsZone[]) => void;
};

type DragState =
  | {
      kind: 'move';
      zoneId: string;
      pointerId: number;
      startClientX: number;
      startClientY: number;
      startX: number;
      startY: number;
    }
  | {
      kind: 'resize';
      zoneId: string;
      handle: ResizeHandle;
      pointerId: number;
      startClientX: number;
      startClientY: number;
      startX: number;
      startY: number;
      startW: number;
      startH: number;
    };

function clampNumber(v: number, min: number, max: number): number {
  return Math.max(min, Math.min(max, v));
}

function to01(v: number): number {
  // Backward compatible: old content used 0..100 (percent)
  if (!Number.isFinite(v)) return 0;
  return v > 1.5 ? v / 100 : v;
}

function round4(v: number): number {
  return Math.round(v * 10000) / 10000;
}

function normalizeZone01(zone: KidsZone): KidsZone {
  return {
    ...zone,
    x: to01(zone.x),
    y: to01(zone.y),
    width: to01(zone.width),
    height: to01(zone.height),
  };
}

export default function ZoneEditor({ zones, containerWidth, containerHeight, onChangeZones }: Props) {
  const layerRef = useRef<HTMLDivElement | null>(null);

  const zones01 = useMemo(() => zones.map(normalizeZone01), [zones]);

  const [activeZoneId, setActiveZoneId] = useState<string | null>(zones01[0]?.id ?? null);
